(function(root){
 const moods=['','Heartbroken','A rainy day','Not for me','Almost there','Mixed feelings','A good time','A little gem','Wonderful','Extraordinary','An all-time masterpiece'];
 const faces=['','☹','☂','◡','≈','◈','♪','✧','✦','☄','♛'];
 function rate(entry,score){if(!Number.isInteger(score)||score<0||score>10)throw new RangeError('Rating must be 0–10');return {...entry,rating:score};}
 const escape=v=>String(v).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');
 function markup(entry){const score=entry.rating||0;return `<div class="personal-rating" data-rating-id="${escape(entry.id)}"><span class="rating-caption">Your rating <output aria-live="polite">${score?score+' / 10':'Not rated'}</output></span><div class="rating-stars" role="radiogroup" aria-label="Your rating for ${escape(entry.title)}">${Array.from({length:10},(_,i)=>`<button type="button" role="radio" aria-checked="${score===i+1}" aria-label="${i+1} out of 10 stars" tabindex="${(score||1)===i+1?0:-1}" data-rating-score="${i+1}" class="${i<score?'is-filled':''}"><span aria-hidden="true">${i<score?'★':'☆'}</span></button>`).join('')}</div><button type="button" class="rating-clear" ${score?'':'hidden'}>Clear rating</button><span class="rating-mood" role="status">${score?moods[score]:''}</span></div>`;}
 const api={rate,markup};if(typeof module==='object')module.exports=api;
 if(typeof document==='undefined')return;root.FolioRating=api;
 const active=new Set();
 const cancel=()=>{for(const a of active)a.cancel();active.clear();document.querySelectorAll('.rating-celebration').forEach(n=>n.remove());};
 function feedback(widget,score,point){if(!score||!root.FolioMotion?.allowed())return;
  const effect=document.createElement('span');effect.className='rating-celebration';effect.dataset.level=score;effect.setAttribute('aria-hidden','true');const host=widget.closest('dialog')||document.body,zoom=Number.parseFloat(getComputedStyle(document.documentElement).zoom)||1,rect=widget.getBoundingClientRect(),box=host.tagName==='DIALOG'?host.getBoundingClientRect():null;const at=point||{x:rect.left+rect.width/2,y:rect.top+rect.height/2};const position=root.FolioFeedback.coordinates(at.x,at.y,zoom,box?{left:box.left,top:box.top,scale:box.width/host.offsetWidth||zoom,scrollLeft:host.scrollLeft,scrollTop:host.scrollTop,clientLeft:host.clientLeft,clientTop:host.clientTop}:null);effect.style.position=box?'absolute':'fixed';effect.style.left=position.x+'px';effect.style.top=position.y+'px';host.append(effect);
  const classic=document.documentElement.dataset.theme==='yotsuba';const count=classic?1:score===10?18:Math.min(9,score+1);
  for(let i=0;i<count;i++){const particle=document.createElement('i');particle.textContent=classic?(score===1?'(;_;)':score===10?'★ MASTERPIECE ★':'('+score+'/10)'):score===10?(i===0?'♛':'✦'):faces[score];effect.append(particle);
   const angle=i/count*Math.PI*2, distance=score===10?70:20+score*3;
   const animation=particle.animate([{opacity:0,transform:'translate(-50%, 0) scale(.3)'},{opacity:1,offset:.25,transform:`translate(calc(-50% + ${Math.cos(angle)*distance/2}px), ${score<=2?12:-24}px) scale(${score===10?1.6:1})`},{opacity:0,transform:`translate(calc(-50% + ${Math.cos(angle)*distance}px), ${score<=2?40:Math.sin(angle)*distance-25}px) scale(.6)`}],{duration:score===10?1600:850,easing:'cubic-bezier(.2,.7,.3,1)',delay:i*18});active.add(animation);animation.finished.catch(()=>{}).finally(()=>{active.delete(animation);particle.remove();if(!effect.children.length)effect.remove();});
  }
 }
 function save(widget,score,focusScore,point){const id=widget.dataset.ratingId,previous=items.map(e=>({...e}));let current=items;try{const fresh=JSON.parse(localStorage.getItem('folio-library-v1')||'null');if(Array.isArray(fresh)&&fresh.some(e=>e.id===id))current=fresh;}catch{}
  const entry=current.find(e=>e.id===id);if(!entry)return;const changed=entry.rating!==score;if(!changed){feedback(widget,score,point);return;}
  items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(current):current;Object.assign(items.find(e=>e.id===id),rate(entry,score));if(!persist()){items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(previous):previous;return;}render();
  for(const node of [...document.querySelectorAll('.personal-rating')].filter(n=>n.dataset.ratingId===id)){const holder=document.createElement('div');holder.innerHTML=markup(items.find(e=>e.id===id));const next=holder.firstElementChild;node.replaceWith(next);if(node===widget){next.querySelector(`[data-rating-score="${focusScore||score||1}"]`)?.focus({preventScroll:true});feedback(next,score,point);}}
 }
 document.addEventListener('click',e=>{const widget=e.target.closest('.personal-rating');if(!widget)return;const star=e.target.closest('[data-rating-score]');if(star)save(widget,Number(star.dataset.ratingScore),undefined,e.detail?{x:e.clientX,y:e.clientY}:(()=>{const r=star.getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2};})());else if(e.target.closest('.rating-clear'))save(widget,0);});
 document.addEventListener('keydown',e=>{const star=e.target.closest('[data-rating-score]');if(!star||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const score=e.key==='Home'?1:e.key==='End'?10:Math.max(1,Math.min(10,Number(star.dataset.ratingScore)+(['ArrowRight','ArrowUp'].includes(e.key)?1:-1)));const r=star.getBoundingClientRect();save(star.closest('.personal-rating'),score,score,{x:r.left+r.width/2,y:r.top+r.height/2});});
 new MutationObserver(cancel).observe(document.documentElement,{attributes:true,attributeFilter:['data-motion','data-ui-motion','data-theme']});
 matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{if(!root.FolioMotion?.allowed())cancel();});
})(globalThis);
